MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING DUAL ON (T.SQL_ID = 'EndCustomerByDivisionDMF0082')
WHEN MATCHED THEN UPDATE SET T.MDU_DIVS_CD = 'DM', T.SQL_NM = 'DMF0082 End Customer by division (END_CUSTOMER lookup)', T.SQL_DTL_CTN = 'SELECT DISTINCT CODE, NAME FROM ('||CHR(10)||'  /* (1) END_CUSTOMER lookup axis - div 40 표기 원천 [E20260814-ENDCUST] */'||CHR(10)||'  SELECT L.SEGMENT2 AS CODE, NVL(L.SEGMENT3, L.SEGMENT2) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L'||CHR(10)||'  WHERE  L.LOOKUP_TYPE = ''END_CUSTOMER'' AND L.VALID_YN = ''Y'' AND L.SEGMENT2 <> ''-'''||CHR(10)||'  AND    ( NVL(TRIM(@divisionId), ''-'') = ''-'' OR L.SEGMENT1 = TRIM(@divisionId) )'||CHR(10)||'  UNION ALL'||CHR(10)||'  /* (2) div 40 : SITE_ITEM owner axis (AS-IS EndCustomerByDivision40) */'||CHR(10)||'  SELECT A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_MST_SITE_ITEM A'||CHR(10)||'  JOIN   SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))'||CHR(10)||'  JOIN   SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID'||CHR(10)||'  LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'         ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2'||CHR(10)||'        AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'  WHERE  A.VALID_YN = ''Y'' AND TRIM(@divisionId) = ''40'' AND A.DIVISION_ID = ''40'''||CHR(10)||'  UNION ALL'||CHR(10)||'  /* (3) div 81/82 : 조회조건과 동일 축 = SCM_MST_SITE.END_CUSTOMER (AS-IS BigFilter'||CHR(10)||'         EndCustomerByDivision 의 비40 분기 원문과 동일) [E20260818-ENDCUST81] */'||CHR(10)||'  SELECT S.END_CUSTOMER AS CODE, NVL(D.SEGMENT3, S.END_CUSTOMER) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_MST_SITE S'||CHR(10)||'  LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'         ON D.SEGMENT1 = S.DIVISION_ID AND D.SEGMENT2 = S.END_CUSTOMER'||CHR(10)||'        AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'  WHERE  S.END_CUSTOMER IS NOT NULL AND NVL(TRIM(@divisionId), ''-'') <> ''-'''||CHR(10)||'  AND    S.DIVISION_ID = TRIM(@divisionId) AND TRIM(@divisionId) <> ''40'''||CHR(10)||') ORDER BY NAME', T.USE_YN = 'Y', T.CREATED_BY = 'admin', T.CREATION_DATE = TO_DATE('20260814085449','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = TO_DATE('20260818175330','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('EndCustomerByDivisionDMF0082', 'DM', 'DMF0082 End Customer by division (END_CUSTOMER lookup)', 'SELECT DISTINCT CODE, NAME FROM ('||CHR(10)||'  /* (1) END_CUSTOMER lookup axis - div 40 표기 원천 [E20260814-ENDCUST] */'||CHR(10)||'  SELECT L.SEGMENT2 AS CODE, NVL(L.SEGMENT3, L.SEGMENT2) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L'||CHR(10)||'  WHERE  L.LOOKUP_TYPE = ''END_CUSTOMER'' AND L.VALID_YN = ''Y'' AND L.SEGMENT2 <> ''-'''||CHR(10)||'  AND    ( NVL(TRIM(@divisionId), ''-'') = ''-'' OR L.SEGMENT1 = TRIM(@divisionId) )'||CHR(10)||'  UNION ALL'||CHR(10)||'  /* (2) div 40 : SITE_ITEM owner axis (AS-IS EndCustomerByDivision40) */'||CHR(10)||'  SELECT A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_MST_SITE_ITEM A'||CHR(10)||'  JOIN   SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))'||CHR(10)||'  JOIN   SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID'||CHR(10)||'  LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'         ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2'||CHR(10)||'        AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'  WHERE  A.VALID_YN = ''Y'' AND TRIM(@divisionId) = ''40'' AND A.DIVISION_ID = ''40'''||CHR(10)||'  UNION ALL'||CHR(10)||'  /* (3) div 81/82 : 조회조건과 동일 축 = SCM_MST_SITE.END_CUSTOMER (AS-IS BigFilter'||CHR(10)||'         EndCustomerByDivision 의 비40 분기 원문과 동일) [E20260818-ENDCUST81] */'||CHR(10)||'  SELECT S.END_CUSTOMER AS CODE, NVL(D.SEGMENT3, S.END_CUSTOMER) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_MST_SITE S'||CHR(10)||'  LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'         ON D.SEGMENT1 = S.DIVISION_ID AND D.SEGMENT2 = S.END_CUSTOMER'||CHR(10)||'        AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'  WHERE  S.END_CUSTOMER IS NOT NULL AND NVL(TRIM(@divisionId), ''-'') <> ''-'''||CHR(10)||'  AND    S.DIVISION_ID = TRIM(@divisionId) AND TRIM(@divisionId) <> ''40'''||CHR(10)||') ORDER BY NAME', 'Y', 'admin', TO_DATE('20260814085449','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260818175330','YYYYMMDDHH24MISS'));

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING DUAL ON (T.SQL_ID = 'FcstTypeByUserGroupDMF0082')
WHEN MATCHED THEN UPDATE SET T.MDU_DIVS_CD = 'DM', T.SQL_NM = 'DMF0082 FCST Type 표시용 (division 전달 시 W/S 분기 — AS-IS UP_FX_GetCommonDataList_DM)', T.SQL_DTL_CTN = 'SELECT CODE, NAME, DISPLAY_SEQ FROM ('||CHR(10)||'  /* [E20260814-WSDIV → E20260819-FCSTTYPE6] 81 계열 + DM Planner(W/S)'||CHR(10)||'     → SALES_TYPE_CODE2 ∪ SALES_TYPE_CODE2_ADD 6종 (2026-08-19 통합테스트 —'||CHR(10)||'     AS-IS DMF0003 FcstTypeEditMode 동형. 구 4종엔 CODE2_ADD(Recall/RMA) 누락) */'||CHR(10)||'  SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME'||CHR(10)||'       , CASE LOOKUP_TYPE WHEN ''SALES_TYPE_CODE2'' THEN DISPLAY_SEQ ELSE 100 + DISPLAY_SEQ END AS DISPLAY_SEQ'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'  WHERE  LOOKUP_TYPE IN (''SALES_TYPE_CODE2'', ''SALES_TYPE_CODE2_ADD'')'||CHR(10)||'  AND    VALID_YN = ''Y'''||CHR(10)||'  AND    NVL(TRIM(@divisionId), ''-'') LIKE ''81%'''||CHR(10)||'  AND    EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G'||CHR(10)||'                 WHERE G.USER_ID = @sesUserId AND G.USER_GR_ID = ''DM Planner (W/S)'' AND G.USE_YN = ''Y'')'||CHR(10)||'  UNION ALL'||CHR(10)||'  /* division 전달 + W/S 자격 아님 → SALES_TYPE_CODE 에서 전용플래그(ATTRIBUTE2=''Y'' — 실측 WS/WSF 2건 유일) 제외 = 12종 */'||CHR(10)||'  SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME, DISPLAY_SEQ'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'  WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE'''||CHR(10)||'  AND    VALID_YN = ''Y'''||CHR(10)||'  AND    NVL(ATTRIBUTE2, '' '') <> ''Y'''||CHR(10)||'  AND    NVL(TRIM(@divisionId), ''-'') <> ''-'''||CHR(10)||'  AND    NOT ( NVL(TRIM(@divisionId), ''-'') LIKE ''81%'''||CHR(10)||'               AND EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G'||CHR(10)||'                           WHERE G.USER_ID = @sesUserId AND G.USER_GR_ID = ''DM Planner (W/S)'' AND G.USE_YN = ''Y'') )'||CHR(10)||'  UNION ALL'||CHR(10)||'  /* division 미전달(메타 셀 콤보 = CODE->NAME 표시 매핑) → 전 코드 1행씩 (중복 없음) */'||CHR(10)||'  SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME, DISPLAY_SEQ'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'  WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE'''||CHR(10)||'  AND    VALID_YN = ''Y'''||CHR(10)||'  AND    NVL(TRIM(@divisionId), ''-'') = ''-'''||CHR(10)||') ORDER BY DISPLAY_SEQ, CODE', T.USE_YN = 'Y', T.CREATED_BY = 'admin', T.CREATION_DATE = TO_DATE('20260807192239','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = TO_DATE('20260819234216','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
