_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'  WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE'''||CHR(10)||'  AND    VALID_YN = ''Y'''||CHR(10)||'  AND    NVL(TRIM(@divisionId), ''-'') = ''-'''||CHR(10)||') ORDER BY DISPLAY_SEQ, CODE', 'Y', 'admin', TO_DATE('20260807192239','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260819234216','YYYYMMDDHH24MISS'));

